std:sqlite.documentation:
Opens a synchronous SQLite connection. Creates missing files; :memory: creates a private in-memory database. Foreign keys start enabled. busyTimeout accepts 0..2147483647 ms; omit it or pass undefined for 5000 ms. Zero disables waiting. Invalid path/range, filesystem and SQLite errors return SqliteError. Does not mutate arguments.

```tsrust
const db = unwrap(open(':memory:'));
unwrap(db.close());
```

Ownership: owns the connection; scope exit closes it. Blocking work must not run on an async executor worker.

examples.source:
import { open, Row } from 'std:sqlite';

type Person = { id: int; name: string; };

function person(row: ReadOnly<Row>): Person {
  return { id: unwrap(row.int('id')), name: unwrap(row.text('name')) };
}

function main(): void {
  const db = unwrap(open(':memory:'));
  {
    const create = unwrap(db.prepare('CREATE TABLE people(id INTEGER PRIMARY KEY, name TEXT NOT NULL)'));
    unwrap(create.execute());
  }
  {
    const transaction = unwrap(db.begin());
    {
      const insert = unwrap(transaction.prepare('INSERT INTO people(id, name) VALUES (?1, ?2)'));
      unwrap(insert.execute([1, 'Ada']));
      unwrap(insert.execute([2, 'Grace']));
    }
    unwrap(transaction.commit());
  }
  {
    const select = unwrap(db.prepare('SELECT id, name FROM people ORDER BY id'));
    const rows = unwrap(select.query());
    for (const row of rows) {
      const value = person(row);
      console.log(`${value.id}: ${value.name}`);
    }
  }
  unwrap(db.close());
}

std:sqlite.documentation:
Owned synchronous database handle. Use open(path), prepare(sql), begin() and close(). Scope exit closes it; live statements or transactions prevent explicit close.

```tsrust
import { open, Row } from 'std:sqlite';

type Person = {
  id: int;
  name: string;
};

function person(row: ReadOnly<Row>): Person {
  return {
    id: unwrap(row.int('id')), name: unwrap(row.text('name'))
  };
}

function main(): void {
  const db = unwrap(open(':memory:'));
  {
    const create = unwrap(db.prepare('CREATE TABLE people(id INTEGER PRIMARY KEY, name TEXT NOT NULL)'));
    unwrap(create.execute());
  }

  {
    const transaction = unwrap(db.begin());
    {
      const insert = unwrap(transaction.prepare('INSERT INTO people(id, name) VALUES (?1, ?2)'));
      unwrap(insert.execute([1, 'Ada']));
      unwrap(insert.execute([2, 'Grace']));
    }

    unwrap(transaction.commit());
  }

  {
    const select = unwrap(db.prepare('SELECT id, name FROM people ORDER BY id'));
    const rows = unwrap(select.query());

    for (const row of rows) {
      const value = person(row);
      console.log(`${value.id}: ${value.name}`);
    }
  }

  unwrap(db.close());
}

// 1: Ada
// 2: Grace
```

Ownership: The connection is uniquely owned. Statements and transactions retain borrows; close consumes the connection.

