Reports whether the current worker has received a cancellation request. Takes no arguments; returns false outside workers. Poll during long loops and exit promptly when true. Checking does not interrupt execution or throw; after callback exit, join reports cancelled if the request won the completion race. Nested pool execution preserves each worker’s own cancellation context.

Ownership: does not access or consume caller-owned handles.

```tsrust
import { spawn, cancellationRequested } from "std:threads";

function slowSum(): int {
  let sum = 0;

  for (let i = 0; i < 100000000; i++) {
    if (cancellationRequested()) return -1; // no TaskContext needed
    sum += 1;
  }

  return sum;
}

function main() {
  console.log(cancellationRequested()); // false outside a worker
  const worker = unwrap(spawn((): int => slowSum()));
  worker.cancel();

  match (worker.join()) {
    Ok(value) => {
      console.log(value === -1 ? "stopped early" : "finished");
    },
    Err(error) => {
      console.log(error.code);
    }
  }
}
// prints: false
// prints: cancelled
```
