```tsrust
const actions: (() => int)[] = [(): int => {
  return 7;
}, (): int => {
  return 9;
}];
console.log(actions.reduce((sum: int, action: Mutable<Function<int>>): int => {
  return sum + action();
}, 0)); // prints "16"
```

