const removed = values.shift();
console.log(String(removed), values.length, values.join("|")); // 1 2 2|3
let empty: int[] = [];
console.log(String(empty.shift()), empty.length);
empty.push(7);
console.log(String(empty.shift()), String(empty.shift()), empty.length);
// undefined 0
// 7 undefined 0
```

