Creates a unique synthetic native resource with a positive process-local identity and real destructor. Takes no arguments. Returns an owned opaque resource. Identity exhaustion terminates native execution before reuse. Scope exit, replacement and consuming closeResource release its native allocation. This test instrument is not a file, database or UI backend.

The resource cannot be cloned, projected or transferred to worker threads or started tasks. Direct local ownership and borrowing apply. No asynchronous cleanup completion is implied.

```tsrust
const r = trackedResource();
const key = resourceId(r);
closeResource(r);
strictEqual(releaseCount(key), 1);
```

Ownership: resource operations use checked borrowing or consumption; audit integers copy without retaining resources.

examples.source:
import {trackedResource,resourceId,closeResource,releaseCount,releaseOrder,liveCount,TrackedResource} from "std:testing";
import {strictEqual,ok} from "std:testing";
type State = {resource: TrackedResource;};
function returned():TrackedResource {return trackedResource();}
function main(){
 const baseline=liveCount();
 let first=0;
 let second=0;
 {
  let state:State={resource:returned()};
  first=resourceId(state.resource);
  strictEqual(releaseCount(first),0);
  state={resource:trackedResource()};
  second=resourceId(state.resource);
  strictEqual(releaseCount(first),1);
  strictEqual(releaseCount(second),0);
 }
 strictEqual(releaseCount(second),1);
 ok(releaseOrder(first)<releaseOrder(second));
 let captured=0;
 {
  const resource=trackedResource();
  captured=resourceId(resource);
  const callback=():int=>{return resourceId(resource);};
  strictEqual(callback(),captured);
  strictEqual(callback(),captured);
  strictEqual(releaseCount(captured),0);
 }
 strictEqual(releaseCount(captured),1);
 let removed=0;
 {
  const items:TrackedResource[]=[];
  const item=trackedResource();
  removed=resourceId(item);
  items.push(item);
  strictEqual(releaseCount(removed),0);
  const extracted=items.remove(0);
  strictEqual(releaseCount(removed),0);
  closeResource(extracted);
 }
 strictEqual(releaseCount(removed),1);
 const resource=trackedResource();
 const identity=resourceId(resource);
 closeResource(resource);
 strictEqual(releaseCount(identity),1);
 strictEqual(liveCount(),baseline);
 console.log("resources released once");
}

