    match (writeTextFileAtomic('catalog-atomic', 'hello')) {
      Ok(_) => {
        throw 'Expected unsupported';
      },
      Err(error) => {
        console.log(error.code);
      }
    }

    return;
  }

  unwrap(writeTextFileAtomic('catalog-atomic', 'hello'));
  unwrap(writeTextFileAtomic('catalog-atomic', 'edited', 'hello'));
  console.log(unwrap(readTextFile('catalog-atomic')));
  unwrap(removeFile('catalog-atomic'));
}
```
Expected output: edited. Windows: unsupported.

