Moves a plain file cursor relative to byte zero, its current cursor, or its file length, returning the resulting absolute byte position. It changes no file contents; seeking past EOF is allowed by ordinary files, and later reads return empty until data is available. A negative start offset returns offset-range before accessing the file. Signed current/end offsets use host seek behavior; an invalid resulting position or non-seekable handle returns FsError. The returned position must fit int; integer-range can be reported after a successful host seek has already moved the cursor. No application offset cap or implicit default origin is imposed. Ownership: mutably borrows the unique File and leaves it open; the literal origin selector copies.

```tsrust
import { toUtf8 } from "std:bytes";
import {
  createTempDir,
  writeTextFile,
  open,
  seek,
  read,
  close,
  removeDirAll,
  SeekOrigin
} from "std:fs";

function main() {
  const directory = unwrap(createTempDir(".", "catalog-seek-"));
  const path = directory + "/input";
  unwrap(writeTextFile(path, "abcd"));
  const file = unwrap(open(path));
  const origin: SeekOrigin = "start";
  console.log(unwrap(seek(file, 2, origin)));
  console.log(unwrap(toUtf8(unwrap(read(file, 2)))));
  unwrap(close(file));
  unwrap(removeDirAll(directory));
}
```

Expected output:
```text
2
cd
```

