function main() {
  match (fromArray([0, 65, 255])) {
    Ok(bytes) => {
      match (copy(bytes, 1, 3)) {
        Ok(part) => {
          console.log(length(part));
        },
        Err(error) => {
          console.log(error.message);
        }
      }
    },
    Err(error) => {
      console.log(error.message);
    }
  }
}
