An exclusive, writable window onto bytes owned by another value, created by `viewMut` without copying. `set` writes through it to the owner; `length`, `at`, `copy` and `toUtf8` read it. Its length is fixed.

While it exists, the owner cannot be used at all and no other view of those bytes can exist. It cannot be cloned.

```tsrust
import { ByteViewMut, fromArray, viewMut, set, at } from "std:bytes";

function clear(part: Mutable<ByteViewMut>) {
  match (set(part, 0, 0)) {
    Ok(_) => {},
    Err(error) => {
      console.log(error.message);
    },
  }
}

function main() {
  match (fromArray([7, 8])) {
    Ok(bytes) => {
      match (viewMut(bytes, 1, 2)) {
        Ok(part) => {
          clear(part);
        },
        Err(error) => {
          console.log(error.message);
        },
      }

      match (at(bytes, 1)) {
        Ok(value) => {
          console.log(value);
        },
        Err(error) => {
          console.log(error.message);
        },
      }
    },
    Err(error) => {
      console.log(error.message);
    },
  }
}
```

