  const values: JsonValue[] = [fromInt(1), fromInt(2), fromInt(3)];

  match (fromArray(values, limits)) {
    Ok(value) => {
      console.log(JSON.stringify(value));
    },
    Err(error) => {
      console.log(error.code);
    }
  }
}
// prints: entry-limit
