import { fromUtf8 } from "std:bytes";
import { writeFile } from "std:fs";
import { openJsonl, readJsonl, closeJsonl, kind } from "std:json";

function main() {
  unwrap(writeFile("events.jsonl", unwrap(fromUtf8('{"n":1}\nnull\n{"n":2}\n'))));
  const reader = unwrap(openJsonl("events.jsonl"));
  let record = unwrap(readJsonl(reader));

  while (record !== undefined) {
    console.log(kind(record), JSON.stringify(record));
    record = unwrap(readJsonl(reader));
  }

  unwrap(closeJsonl(reader));
}
// prints: object {"n":1}
// prints: null null
// prints: object {"n":2}
```

