    Ok(bytes) => {
      match (writeFile("jsonl-example.jsonl", bytes)) {
        Ok(_) => {},
        Err(e) => {
          throw e.message;
        }
      }
    },
    Err(e) => {
      throw e.message;
    }
  }

  match (openJsonl("jsonl-example.jsonl")) {
    Ok(reader) => {
      match (readJsonl(reader)) {
        Ok(value) => {
          if (value === undefined) {
            throw "unexpected EOF";
          }

          console.log(kind(value));
        },
        Err(e) => {
          throw e.message;
        }
      }

      match (closeJsonl(reader)) {
        Ok(_) => {},
        Err(e) => {
          throw e.message;
        }
      }
    },
    Err(e) => {
      throw e.message;
    }
  }
}
