    }
  }

  match (openJsonl("jsonl-example.jsonl")) {
    Ok(reader) => {
      match (readJsonl<Item>(reader)) {
        Ok(value) => {
          if (value === undefined) {
            throw "unexpected EOF";
          }

          console.log(value.name);
        },
        Err(e) => {
          throw e.message;
        }
      }

      match (closeJsonl(reader)) {
        Ok(_) => {},
        Err(e) => {
          throw e.message;
        }
      }
    },
    Err(e) => {
      throw e.message;
    }
  }
}
```

Also accepts a `JsonlReaderView` from `borrowJsonl`.

Ownership: mutably borrows the reader; each value owns its data and outlives the reader.

Closes a JSON Lines reader early and releases its buffer. Returns Ok on successful close or JsonlError for a close failure. If EOF/error already released the file, close succeeds without closing another descriptor. A prior read error was already returned by readJsonl and is not repeated by close. No implicit sync occurs.

```tsrust
import { fromUtf8 } from "std:bytes";
import { writeFile } from "std:fs";
import { openJsonl, readJsonl, closeJsonl } from "std:json";

function main() {
  unwrap(writeFile("events.jsonl", unwrap(fromUtf8('{"n":1}\nnull\n{"n":2}\n'))));
  const reader = unwrap(openJsonl("events.jsonl"));
  const first = unwrap(readJsonl(reader)); // owned; survives the close below
  unwrap(closeJsonl(reader)); // stop early without reading the rest
  console.log(JSON.stringify(first));
}
// prints: {"n":1}
```

Ownership: consumes the reader. Scope exit also releases it, but cannot report close errors.

For JsonlReaderView, consumes only the adapter and returns Ok without closing the underlying buffered reader. Unread buffered bytes remain available to the owner.

An opaque owned JSON Lines output resource created by createJsonl. No public constructor or fields. Writes compact records through a bounded staging buffer and a buffered file. flushJsonl reports buffered output failures; closeJsonlWriter consumes the writer and reports cleanup errors. Scope exit closes remaining output but cannot report errors. Ownership: unique, nonclonable and nonconstructible; never shared implicitly.

```tsrust
import { toUtf8 } from "std:bytes";
import { readFile } from "std:fs";
import { createJsonl, writeJsonl, flushJsonl, closeJsonlWriter } from "std:json";

type Event = {
  name: string;
  count: int;
};

function main() {
  {
    const writer = unwrap(createJsonl("audit.jsonl"));
    unwrap(writeJsonl<Event>(writer, {
      name: "login", count: 1
    }));
    // Leaving the block closes the writer; use closeJsonlWriter to see errors.
  }

  console.log(unwrap(toUtf8(unwrap(readFile("audit.jsonl")))).trim());
}
// prints: {"count":1,"name":"login"}
```

Creates or truncates a file for synchronous JSON Lines output. Returns an owned writer or a structured error. Invalid maxBytes reports invalid-limits; invalid capacity reports capacity-range before opening or truncating the path. File errors preserve their stable code and optional OS code. Omitted or undefined maxBytes imposes no record byte quota. Capacity defaults to 8192 bytes; it must be positive and fit the platform. Buffer allocation failure leaves an existing file unchanged. Creation errors use operation create, line 1 and offset 0. Record limits exclude the trailing LF. No record is written by creation. Ownership: borrows path unchanged; returned writer owns its file and buffer.

```tsrust
import { createJsonl, writeJsonl, flushJsonl, closeJsonlWriter } from "std:json";

type Item = {
  name: string;
};

function main() {
  const item: Item = {
    name: "hello"
  };

  match (createJsonl("jsonl-writer-example.jsonl")) {
    Ok(writer) => {
      match (writeJsonl(writer, item)) {
        Ok(_) => {},
        Err(error) => {
          throw error.message;
        }
      }

      match (flushJsonl(writer)) {
        Ok(_) => {},
        Err(error) => {
          throw error.message;
        }
      }

      match (closeJsonlWriter(writer)) {
        Ok(_) => {},
        Err(error) => {
          throw error.message;
        }
      }

      console.log(item.name);
    },
    Err(error) => {
      throw error.message;
    }
  }
}
```

Expected output: hello. The file contains {"name":"hello"} followed by LF.

Writes `value` as one compact JSON line followed by LF, using the `JSON.stringify` rules. Returns `Ok` or a `JsonlError`. A raw record containing a newline makes the writer terminal. `undefined` values return `undefined-value`; a raw record with a newline returns `record-newline` and makes the writer terminal.

The record is staged whole, so an encoding error writes none of it; an I/O error may leave a prefix. Any error is terminal: later writes and flushes repeat it.

```tsrust
import { toUtf8 } from "std:bytes";
import { readFile } from "std:fs";
import { createJsonl, writeJsonl, flushJsonl, closeJsonlWriter } from "std:json";

type Event = {
  name: string;
  count: int;
};

function main() {
  const writer = unwrap(createJsonl("events.jsonl"));
  const events: Event[] = [{
    name: "start", count: 1
  }, {
    name: "stop", count: 2
  }];

  for (const event of events) {
    unwrap(writeJsonl(writer, event));
  }

  unwrap(closeJsonlWriter(writer));
  console.log(unwrap(toUtf8(unwrap(readFile("events.jsonl")))));
}
// prints: {"count":1,"name":"start"}
// prints: {"count":2,"name":"stop"}
```

