Flushes and closes JSON Lines output, releasing its buffer. Always attempts cleanup after a prior write/flush failure. A close failure takes precedence; otherwise a prior terminal error is returned again. Returns Ok when both writing and closing succeeded. New close errors use operation close, offset 0 and the next-record counter. No implicit storage sync occurs. Ownership: consumes the writer even on error; later use is rejected. Scope exit also attempts close but cannot report errors.

```tsrust
import { toUtf8 } from "std:bytes";
import { readFile } from "std:fs";
import { createJsonl, writeJsonl, flushJsonl, closeJsonlWriter } from "std:json";

type Event = {
  name: string;
  count: int;
};

function main() {
  const writer = unwrap(createJsonl("small.jsonl", 30));
  unwrap(writeJsonl<Event>(writer, {
    name: "ok", count: 1
  }));

  match (writeJsonl<Event>(writer, {
    name: "far too long a name", count: 2
  })) {
    Ok(_) => {},
    Err(error) => {
      console.log("write:", error.code);
    }
  }

  match (closeJsonlWriter(writer)) {
    Ok(_) => {
      console.log("closed");
    },
    Err(error) => {
      console.log("close:", error.code); // the earlier terminal error is reported again
    }
  }
}
// prints: write: output-limit
// prints: close: output-limit
```

