std:http.documentation:
Creates a text/event-stream response from an explicitly bounded typed event channel. The backend frames events, preserving individual CR and LF separators; empty data alone dispatches no browser event. No keepalive is installed unless requested. Invalid options throw HttpError code sse; invalid queued event fields become post-header body errors. Dropping the body closes the receiver and pending sends fail. This form does not own or start the producer: keep its Job alive and await it explicitly. Ownership: consumes the channel; borrows options and owns encoded events.

```tsrust
import { Channel, Sender } from 'std:futures';
import { sse, sseWithProducer, SseEvent } from 'std:http';

async function produce(sender: Sender<SseEvent>): Task<void> {
  await sender.send({
    data: 'first', id: '1'
  });
  await sender.send({
    data: 'second\nline', event: 'update', retryMs: 0
  });
}

async function main(): Task<void> {
  const events = new Channel<SseEvent>(1);
  const producer = produce(events.sender()).start();
  const response = sseWithProducer(events, producer);
  console.log(response.header('content-type'));
  console.log((await response.text()).replaceAll('\n', '|'));

  // Channel-only mode keeps the producer's explicit owner outside the body.
  const external = new Channel<SseEvent>(1);
  const externalProducer = produce(external.sender()).start();

  try {
    const response = sse(external);
    console.log((await response.text()).replaceAll('\n', '|'));
  } finally {
    await externalProducer;
  }
}
```

Expected output: text/event-stream
data: first|id: 1||data: second|data: line|event: update|retry: 0||
data: first|id: 1||data: second|data: line|event: update|retry: 0||.

