std:signals.documentation:
Signal registration/receive failure with code runtime, signal, closed or unsupported.

```tsrust
import { listen, SignalError } from "std:signals";

function describe(error: ReadOnly<SignalError>): string {
  return error.code === "unsupported" ? "signals unavailable on this platform" : clone(error.message);
}

async function main(): Task<void> {
  match (listen()) {
    Ok(_) => {
      console.log("listening");
    },
    Err(error) => {
      console.log(describe(error));
    }
  }
}
// prints on macOS and Linux: listening
```

Calling `listen()` outside an async `main` returns code `runtime` with the message "Signal registration requires an async runtime".

