import { parseAddress, listenTcp, connectTcp, TcpListener } from 'std:net';
import { readAll, writeAll, flush } from 'std:io';
import { fromUtf8, toUtf8 } from 'std:bytes';
async function serve(listener: Owned<TcpListener>): Task<void> {
  const [stream, remote] = unwrap(await listener.accept());
  listener.close();
  const request = unwrap(await readAll(stream));
  unwrap(await writeAll(stream, request));
  unwrap(await stream.shutdownWrite());
  stream.close();
}

async function main(): Task<void> {
  const listener = unwrap(await listenTcp(unwrap(parseAddress('127.0.0.1:0'))));
  const endpoint = unwrap(listener.localAddress());
  const server = serve(listener).start();
  try {
    const client = unwrap(await connectTcp(endpoint));
    unwrap(client.setNoDelay(false));
    unwrap(await writeAll(client, unwrap(fromUtf8('ping'))));
    unwrap(await flush(client));
    unwrap(await client.shutdownWrite());
    console.log(unwrap(toUtf8(unwrap(await readAll(client)))));
    client.close();
  } catch (failure) {
    server.cancel();
    try {
      await server;
    } catch (cleanupFailure) {}

    throw failure;
  }

  await server;
}

import { gzip, decompressReader, compressWriter } from 'std:compression';
import { ThreadPool } from 'std:threads';
import { reader, writer, readAll, writeAll, copy, close } from 'std:io';
import { create, readFile, removeFile } from 'std:fs';
import { fromUtf8, toUtf8 } from 'std:bytes';
async function main(): Task<void> {
  const pool = new ThreadPool({ workers: 1, capacity: 1 });
  const input = unwrap(await gzip(pool, unwrap(fromUtf8('one pool pipeline'))));
  const decoded = unwrap(decompressReader(pool, reader(input), 'gzip'));
  const encoded = unwrap(compressWriter(pool, writer(unwrap(create('pipeline.z'))), 'zlib'));
  console.log(unwrap(await copy(decoded, encoded, 7)));
  unwrap(await close(decoded));
  unwrap(await close(encoded));
  const result = unwrap(decompressReader(pool, reader(unwrap(readFile('pipeline.z'))), 'zlib'));
  console.log(unwrap(toUtf8(unwrap(await readAll(result)))));
  unwrap(await close(result));
  unwrap(removeFile('pipeline.z'));
  unwrap(pool.shutdown());
}

